<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {api,send,state,signOut,formatDate,number,type Note,type FileInfo,type WatchItem,type Quote,type User} from '../client';
import Challenge from '../components/Challenge.vue';
import catalogue from '../../api/catalogue.json';
const route=useRoute(),router=useRouter();const section=computed(()=>String(route.params.section||'notes'));
const titles:Record<string,string>={notes:'Research notes',watchlist:'My watchlist',files:'Evidence & files',account:'Account'};
const error=ref(''),message=ref(''),busy=ref(false),loading=ref(false),query=ref(''),noteOffset=ref(0),notes=ref<Note[]>([]),files=ref<FileInfo[]>([]),watchlist=ref<WatchItem[]>([]);
const selected=ref<Note|null>(null);const title=ref(''),content=ref(''),scope=ref<'private'|'public'>('private'),saved=ref('');
const publishToken=ref(''),uploadToken=ref('');const publishChallenge=ref<InstanceType<typeof Challenge>>(),uploadChallenge=ref<InstanceType<typeof Challenge>>();
const fileInput=ref<HTMLInputElement>();const chosenFile=ref<File|null>(null);const publishFile=ref<FileInfo|null>(null);const filePublishChallenge=ref<InstanceType<typeof Challenge>>(),filePublishToken=ref('');
const displayName=ref(state.user?.display_name??''),currentPassword=ref(''),newPassword=ref('');
const symbolQuery=ref(''),page=ref(0),quotes=ref<Quote[]>([]),quoteMeta=ref<{received_at?:string;state?:string;cached?:boolean}>({}),autoRefresh=ref(false),quoteBusy=ref(false);
const directory=Object.entries(catalogue).map(([symbol,meta])=>({symbol,...meta}));
const matches=computed(()=>{const q=symbolQuery.value.trim().toLowerCase();return q?directory.filter(row=>(row.symbol+' '+row.name).toLowerCase().includes(q)).slice(0,12):[];});
const visibleWatchlist=computed(()=>watchlist.value.slice(page.value*20,page.value*20+20));
const dirty=computed(()=>section.value==='notes'&&!!selected.value&&JSON.stringify([title.value,content.value,scope.value])!==saved.value);
let controller:AbortController|undefined,poll:ReturnType<typeof setInterval>|undefined;let generation=0,editorGeneration=0;
function notify(value:string){message.value=value;error.value='';}
function safeDiscard(){if(section.value==='notes'&&busy.value)return false;return !dirty.value||window.confirm('Discard the unsaved changes to this note?');}
function fresh(){if(!safeDiscard())return;editorGeneration++;selected.value={id:'',owner_id:state.user!.id,title:'',body:'',visibility:'private',version:1,created_at:0,updated_at:0};title.value='';content.value='';scope.value='private';saved.value=JSON.stringify(['','','private']);publishToken.value='';}
async function open(note:Note){if(!safeDiscard())return;const editor=++editorGeneration;try{const result=await api<{post:Note}>('/api/posts/'+note.id);if(editor!==editorGeneration||section.value!=='notes')return;selected.value=result.post;title.value=result.post.title;content.value=result.post.body;scope.value=result.post.visibility;saved.value=JSON.stringify([title.value,content.value,scope.value]);publishToken.value='';}catch(e){if(editor===editorGeneration)error.value=(e as Error).message;}}
async function load(){controller?.abort();controller=new AbortController();const current=++generation;loading.value=true;error.value='';try{
 if(section.value==='notes'){const path=query.value?'/api/search?scope=mine&q='+encodeURIComponent(query.value):'/api/posts?scope=mine'+(noteOffset.value?'&offset='+noteOffset.value:'');const result=await api<{items:Note[]}>(path,{signal:controller.signal});if(current===generation)notes.value=result.items;}
 if(section.value==='files'){const result=await api<{items:FileInfo[]}>('/api/files',{signal:controller.signal});if(current===generation)files.value=result.items;}
 if(section.value==='watchlist'){const result=await api<{items:WatchItem[]}>('/api/watchlist',{signal:controller.signal});if(current===generation){watchlist.value=result.items;page.value=Math.min(page.value,Math.max(0,Math.ceil(result.items.length/20)-1));quotes.value=[];quoteMeta.value={};}}
 }catch(e){if((e as Error).name!=='AbortError'&&current===generation)error.value=(e as Error).message;}finally{if(current===generation)loading.value=false;}}
async function saveNote(){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{
 const editing=selected.value.id;const payload={title:title.value,body:content.value,visibility:scope.value,captchaToken:publishToken.value,...(editing?{version:selected.value.version}:{})};
 const result=await send<{id:string;version:number}>('/api/posts'+(editing?'/'+editing:''),payload,editing?'PATCH':'POST');
 selected.value={...selected.value,id:result.id,title:payload.title,body:payload.body,visibility:payload.visibility,version:result.version};saved.value=JSON.stringify([payload.title,payload.body,payload.visibility]);notify(payload.visibility==='public'?'Public note saved. Anyone can read it.':'Private note saved.');await load();
 }catch(e){error.value=(e as Error).message;}finally{busy.value=false;publishToken.value='';publishChallenge.value?.reset();}}
async function deleteNote(note:Note){if(busy.value||!window.confirm('Delete this note? This removes its saved content.'))return;try{await send('/api/posts/'+note.id,{version:note.version},'DELETE');if(selected.value?.id===note.id){editorGeneration++;selected.value=null;}await load();notify('Note deleted.');}catch(e){error.value=(e as Error).message;}}
async function upload(){if(!chosenFile.value||busy.value)return;const file=chosenFile.value;if(file.size>2097152||!file.size){error.value='Choose a non-empty file of at most 2 MiB.';return;}busy.value=true;error.value='';try{await api('/api/files',{method:'POST',body:file,headers:{'Content-Type':file.type,'X-Filename':encodeURIComponent(file.name),'X-Turnstile-Token':uploadToken.value}});chosenFile.value=null;if(fileInput.value)fileInput.value.value='';await load();notify('Uploaded privately.');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;uploadToken.value='';uploadChallenge.value?.reset();}}
async function fileVisibility(file:FileInfo,visibility:'private'|'public'){if(visibility==='public'&&publishFile.value?.id!==file.id){publishFile.value=file;filePublishToken.value='';return;}busy.value=true;try{await send('/api/files/'+file.id,{visibility,...(visibility==='public'?{captchaToken:filePublishToken.value}:{})},'PATCH');publishFile.value=null;await load();notify(visibility==='public'?'File published. Anyone with its link can read it.':'File made private. Previously downloaded copies cannot be recalled.');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;filePublishToken.value='';filePublishChallenge.value?.reset();}}
async function deleteFile(file:FileInfo){if(!window.confirm('Delete '+file.filename+'? Keep an original copy if you need it.'))return;try{await send('/api/files/'+file.id,{},'DELETE');await load();notify('File deleted.');}catch(e){error.value=(e as Error).message;}}
async function addSymbol(symbol:string){try{await send('/api/watchlist',{symbol});symbolQuery.value='';await load();notify('Added to your watchlist.');}catch(e){error.value=(e as Error).message;}}
async function removeSymbol(symbol:string){try{await send('/api/watchlist',{symbol},'DELETE');await load();}catch(e){error.value=(e as Error).message;}}
async function loadQuotes(){if(quoteBusy.value||!visibleWatchlist.value.length)return;const symbols=visibleWatchlist.value.map(item=>item.symbol).join(',');const current=++generation;quoteBusy.value=true;error.value='';try{const result=await api<{rows:Quote[];received_at:string;state:string;cached:boolean}>('/api/markets/quotes?symbols='+encodeURIComponent(symbols));if(section.value==='watchlist'&&current===generation){quotes.value=result.rows;quoteMeta.value=result;}}catch(e){if(section.value==='watchlist')error.value=(e as Error).message;}finally{quoteBusy.value=false;}}
function quoteFor(symbol:string){return quotes.value.find(row=>row.symbol===symbol);}
async function profile(){busy.value=true;try{const result=await send<{user:User}>('/api/account',{displayName:displayName.value},'PATCH');state.user=result.user;notify('Display name saved.');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function changePassword(){busy.value=true;try{await send('/api/account/password',{currentPassword:currentPassword.value,newPassword:newPassword.value});currentPassword.value='';newPassword.value='';notify('Password changed. Other sessions have been signed out.');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function logout(){if(!safeDiscard())return;try{await signOut();selected.value=null;await router.replace('/login');}catch(e){error.value=(e as Error).message;}}
watch(section,()=>{editorGeneration++;selected.value=null;publishFile.value=null;query.value='';noteOffset.value=0;message.value='';quotes.value=[];autoRefresh.value=false;void load();},{immediate:true});
watch(page,()=>{generation++;quotes.value=[];quoteMeta.value={};});
onBeforeRouteLeave(()=>safeDiscard());
onBeforeRouteUpdate(to=>to.params.section===route.params.section||safeDiscard());
const beforeUnload=(event:BeforeUnloadEvent)=>{if(dirty.value){event.preventDefault();event.returnValue='';}};
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);poll=setInterval(()=>{if(section.value==='watchlist'&&autoRefresh.value&&!document.hidden)void loadQuotes();},60000);});
onBeforeUnmount(()=>{controller?.abort();generation++;editorGeneration++;clearInterval(poll);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template><div class="workspace"><aside class="workspace-nav"><div class="workspace-label">MY WORKSPACE</div><RouterLink v-for="item in [['notes','Research notes','01'],['watchlist','Watchlist','02'],['files','Evidence & files','03'],['account','Account','04']]" :key="item[0]" :to="'/app/'+item[0]"><span>{{item[2]}}</span>{{item[1]}}</RouterLink><p>Private by default.<br>Publish deliberately.</p><button class="text-button" @click="logout">Sign out →</button></aside><main class="workspace-main"><header class="workspace-heading"><div><div class="eyebrow">{{state.user?.display_name}} / WORKSPACE</div><h1>{{titles[section]}}</h1></div><span class="version-label">MERIDIAN 6.0</span></header><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
 <template v-if="section==='notes'"><form class="workspace-toolbar" @submit.prevent="noteOffset=0;load()"><input v-model="query" aria-label="Search my notes" maxlength="100" placeholder="Search your notes"><button>Search</button><span class="spacer"></span><button type="button" class="primary" @click="fresh">+ New note</button></form><div class="notes-workspace"><section class="note-index"><p v-if="loading" class="empty">Loading…</p><button v-for="note in notes" :key="note.id" :class="{active:selected?.id===note.id}" @click="open(note)"><span class="visibility">{{note.visibility}}</span><strong>{{note.title}}</strong><small>{{formatDate(note.updated_at)}}</small></button><p v-if="!notes.length&&!loading" class="empty">No matching notes. Start with a question.</p><div v-if="!query" class="pager"><button type="button" :disabled="loading||noteOffset===0" @click="noteOffset=Math.max(0,noteOffset-25);load()">Previous</button><button type="button" :disabled="loading||notes.length<25" @click="noteOffset+=25;load()">Next</button></div></section><form v-if="selected" class="note-editor" @submit.prevent="saveNote"><div class="editor-top"><label>Title<input v-model="title" required maxlength="160" placeholder="What are you investigating?"></label><span v-if="dirty" class="unsaved">Unsaved</span></div><label class="body-label">Research note<textarea v-model="content" required maxlength="10000" rows="14" placeholder="Hypothesis&#10;&#10;Evidence&#10;&#10;Open questions&#10;&#10;What would change my mind?"></textarea></label><div class="editor-settings"><label>Visibility<select v-model="scope"><option value="private">Private — only me</option><option value="public">Public — anyone</option></select></label><span>{{content.length}} / 10,000</span></div><p v-if="scope==='public'" class="hint">Publishing makes this note readable without an account.</p><Challenge v-if="scope==='public'" ref="publishChallenge" action="publish" @update:token="publishToken=$event"/><div class="editor-actions"><button class="primary" :disabled="busy||scope==='public'&&!publishToken">{{busy?'Saving…':scope==='public'?'Save public note':'Save private note'}}</button><RouterLink v-if="selected.id&&selected.visibility==='public'" :to="'/research/'+selected.id">Open public page ↗</RouterLink><span class="spacer"></span><button v-if="selected.id" type="button" class="danger-link" @click="deleteNote(selected)">Delete</button></div></form><div v-else class="editor-empty"><span>01 / RESEARCH NOTES</span><h2>A place for your next question.</h2><p>Save a private working note, collect evidence and publish when you choose.</p><button class="primary" @click="fresh">Write your first note</button></div></div></template>
 <template v-if="section==='files'"><div class="file-intro"><p>Keep supporting evidence with your research. Uploads are private until you publish them.</p><small>PNG, JPEG, WebP or PDF · 2 MiB each · 20 MiB / 50 files per account</small></div><form class="upload-form" @submit.prevent="upload"><label>Choose evidence<input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" @change="chosenFile=($event.target as HTMLInputElement).files?.[0]??null"></label><Challenge ref="uploadChallenge" action="upload" @update:token="uploadToken=$event"/><button class="primary" :disabled="busy||!chosenFile||!uploadToken">{{busy?'Uploading…':'Upload privately'}}</button></form><form v-if="publishFile" class="publish-file" @submit.prevent="fileVisibility(publishFile,'public')"><strong>Publish {{publishFile.filename}}?</strong><p>Anyone with its link will be able to read it. Downloaded copies cannot be recalled.</p><Challenge ref="filePublishChallenge" action="publish" @update:token="filePublishToken=$event"/><button class="primary" :disabled="busy||!filePublishToken">Confirm public access</button><button type="button" @click="publishFile=null">Cancel</button></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Filename</th><th>Size</th><th>Access</th><th>Actions</th></tr></thead><tbody><tr v-for="file in files" :key="file.id"><td><a :href="file.url" target="_blank" rel="noopener noreferrer">{{file.filename}} ↗</a><small>{{file.mime}}</small></td><td>{{number(file.bytes/1024)}} KiB</td><td><span class="visibility">{{file.visibility}}</span></td><td><button v-if="file.visibility==='private'" @click="fileVisibility(file,'public')">Publish…</button><button v-else @click="fileVisibility(file,'private')">Make private</button><button class="danger-link" @click="deleteFile(file)">Delete</button></td></tr></tbody></table><p v-if="!files.length&&!loading" class="empty">No files yet. Originals stay with you; these copies support your notes.</p></div></template>
 <template v-if="section==='watchlist'"><div class="watchlist-intro"><p>A focused list, with public snapshots on request. No background market stream.</p><small>5,000 configured securities · up to 50 saved · 20 visible quotes per request</small></div><form class="workspace-toolbar" @submit.prevent="matches[0]&&addSymbol(matches[0].symbol)"><label class="sr-only" for="security-search">Find a security</label><input id="security-search" v-model="symbolQuery" placeholder="Ticker or Chinese security name" maxlength="80"><button :disabled="!matches.length">Add first match</button><span class="spacer"></span><button type="button" class="primary" :disabled="quoteBusy||!visibleWatchlist.length" @click="loadQuotes">{{quoteBusy?'Fetching…':'Get visible quotes'}}</button><label class="poll-toggle"><input v-model="autoRefresh" type="checkbox"> Update every 60 seconds</label></form><ul v-if="matches.length" class="symbol-matches"><li v-for="item in matches" :key="item.symbol"><button @click="addSymbol(item.symbol)"><strong>{{item.symbol}}</strong><span>{{item.name}}</span><small>Add +</small></button></li></ul><div class="source-status"><span>{{quoteMeta.state==='partial'?'Partial source response':quoteMeta.received_at?'Snapshot received':'Quotes have not been requested'}}</span><span v-if="quoteMeta.received_at">Retrieved {{new Date(quoteMeta.received_at).toLocaleString()}}{{quoteMeta.cached?' · cached ≤60s':''}}</span><span>Upstream delay unverified</span></div><div class="table-scroll"><table class="data-table market-table"><thead><tr><th>Security</th><th>Latest</th><th>Change %</th><th>Source time</th><th></th></tr></thead><tbody><tr v-for="item in visibleWatchlist" :key="item.symbol"><td><strong>{{item.symbol}}</strong><small>{{item.name}}</small></td><td>{{number(quoteFor(item.symbol)?.price)}} <small>{{item.currency}}</small></td><td :class="{gain:(quoteFor(item.symbol)?.change_pct??0)>0,loss:(quoteFor(item.symbol)?.change_pct??0)<0}">{{number(quoteFor(item.symbol)?.change_pct)}}</td><td>{{quoteFor(item.symbol)?.source_time??'—'}}</td><td><button class="text-button" @click="removeSymbol(item.symbol)">Remove</button></td></tr></tbody></table><p v-if="!watchlist.length&&!loading" class="empty">Search the directory to start your own watchlist.</p></div><div class="pager"><button :disabled="page===0" @click="page--">Previous</button><span>Page {{page+1}} / {{Math.max(1,Math.ceil(watchlist.length/20))}}</span><button :disabled="(page+1)*20>=watchlist.length" @click="page++">Next</button></div><p class="hint">Red gains / green losses follow Chinese market convention. Prices are observations, not execution offers.</p></template>
 <template v-if="section==='account'"><section class="account-details"><h2>Your account</h2><p>{{state.user?.email}}</p><p class="hint">Email is your login identifier. Email verification and recovery by email are not available in this edition.</p><form @submit.prevent="profile"><label>Display name<input v-model="displayName" maxlength="80" required></label><button class="primary" :disabled="busy">Save display name</button></form><form @submit.prevent="changePassword"><h2>Change password</h2><label>Current password<input v-model="currentPassword" type="password" autocomplete="current-password" minlength="12" maxlength="128" required></label><label>New password<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><button class="primary" :disabled="busy">Change password</button><p class="hint">This signs out your other sessions.</p></form></section></template>
 </main></div></template>
